# ---------------------------------------------------------------------------

# Roles a paper can play relative to the project. Used by Related Work drafting
# (foundation papers anchor narratives; direct-competitor papers must be cited).
VALID_ROLES: frozenset[str] = frozenset(
    {"foundation", "direct-competitor", "method-component", "evaluation", "background"}
)

# Modes for read_literature_map — keep token usage proportional to need.
VALID_READ_MODES: frozenset[str] = frozenset(
    {"summary", "competitors", "unverified", "bib", "full"}
)

# Fields kept in summary mode (skips long fields like abstract, relevance).
_SUMMARY_FIELDS: tuple[str, ...] = (
    "title", "year", "venue", "category", "role", "verified", "bibtex_key",
)


